#include "Tr.h"

#include "TranslationsData.inc" // generated by tools/po2inc.cpp from translations/*/LC_MESSAGES/*.po

#include <windows.h>

#include <algorithm>
#include <cctype>
#include <unordered_map>

namespace nsp {

namespace {

struct Catalog
{
    const TrLanguage *lang = nullptr; // nullptr: English
    std::unordered_map<std::string_view, const TrEntry *> map;
    std::string code;
    std::vector<std::function<void()>> listeners;
};

Catalog &catalog()
{
    static Catalog c;
    return c;
}

std::vector<Language> buildLanguages()
{
    std::vector<Language> out;
    for (const auto &l : kTrLanguages)
        if (l.code)
            out.push_back({ l.code, l.name });
    return out;
}

const TrEntry *find(std::string_view key)
{
    const auto &c = catalog();
    if (!c.lang)
        return nullptr;
    auto it = c.map.find(key);
    return it == c.map.end() ? nullptr : it->second;
}

std::string lower(std::string_view s)
{
    std::string out(s);
    for (auto &ch : out) {
        ch = char(std::tolower(uint8_t(ch)));
        if (ch == '_')
            ch = '-';
    }
    return out;
}

std::string_view base(std::string_view tag) { return tag.substr(0, tag.find('-')); }

} // namespace

std::span<const Language> languages()
{
    static const std::vector<Language> list = buildLanguages();
    return list;
}

std::string resolveLanguage(std::span<const std::string> preferred, std::span<const std::string> available)
{
    auto pick = [&](std::string_view want) -> const std::string * {
        for (const auto &a : available)
            if (lower(a) == want)
                return &a;
        return nullptr;
    };
    for (const auto &tag : preferred) {
        const std::string t = lower(tag);
        if (t.empty())
            continue;
        if (auto *a = pick(t))
            return *a;
        const std::string_view b = base(t);
        if (b == "en")
            return {};
        if (b == "zh") {
            // zh-Hant(-*), zh-TW, zh-HK, zh-MO: Traditional; zh, zh-Hans(-*), zh-CN, zh-SG: Simplified.
            const bool traditional = t.find("-hant") != std::string::npos || t.ends_with("-tw") ||
                                     t.ends_with("-hk") || t.ends_with("-mo");
            if (auto *a = pick(traditional ? "zh-tw" : "zh-cn"))
                return *a;
        }
        for (const auto &a : available)
            if (base(lower(a)) == b)
                return a;
    }
    return {};
}

std::vector<std::string> windowsLanguages()
{
    std::vector<std::string> out;
    ULONG count = 0, size = 0;
    if (GetUserPreferredUILanguages(MUI_LANGUAGE_NAME, &count, nullptr, &size) && size > 0) {
        std::wstring buf(size, L'\0');
        if (GetUserPreferredUILanguages(MUI_LANGUAGE_NAME, &count, buf.data(), &size)) {
            for (const wchar_t *p = buf.c_str(); *p; p += wcslen(p) + 1) {
                std::string tag;
                for (const wchar_t *q = p; *q; ++q)
                    tag.push_back(char(*q)); // language tags are ASCII
                out.push_back(tag);
            }
        }
    }
    if (out.empty()) {
        wchar_t name[LOCALE_NAME_MAX_LENGTH]{};
        if (LCIDToLocaleName(MAKELCID(GetUserDefaultUILanguage(), SORT_DEFAULT), name, LOCALE_NAME_MAX_LENGTH, 0) > 0) {
            std::string tag;
            for (const wchar_t *q = name; *q; ++q)
                tag.push_back(char(*q));
            out.push_back(tag);
        }
    }
    return out;
}

std::string resolveSetting(std::string_view setting)
{
    std::vector<std::string> available;
    for (const auto &l : languages())
        available.emplace_back(l.code);
    if (setting.empty() || lower(setting) == "auto")
        return resolveLanguage(windowsLanguages(), available);
    if (lower(setting) == "en")
        return {};
    const std::vector<std::string> one{ std::string(setting) };
    return resolveLanguage(one, available);
}

bool setLanguage(std::string_view code)
{
    auto &c = catalog();
    const TrLanguage *found = nullptr;
    if (!code.empty() && lower(code) != "en")
        for (const auto &l : kTrLanguages)
            if (l.code && lower(l.code) == lower(code))
                found = &l;
    const bool ok = found || code.empty() || lower(code) == "en";
    if (found != c.lang) {
        c.lang = found;
        c.map.clear();
        c.code = found ? found->code : "";
        if (found) {
            c.map.reserve(found->count);
            for (size_t i = 0; i < found->count; ++i)
                c.map.emplace(found->entries[i].key, &found->entries[i]);
        }
        auto listeners = c.listeners; // a callback may register another
        for (auto &fn : listeners)
            fn();
    }
    return ok;
}

const std::string &currentLanguage() { return catalog().code; }

void onLanguageChanged(std::function<void()> fn) { catalog().listeners.push_back(std::move(fn)); }

const char *tr(const char *msgid)
{
    if (auto *e = find(msgid))
        return e->str;
    return msgid;
}

const char *trc(const char *context, const char *msgid)
{
    if (!catalog().lang)
        return msgid;
    std::string key = std::string(context) + '\x04' + msgid;
    if (auto *e = find(key))
        return e->str;
    return msgid;
}

std::string detail::pluralLookup(const char *singular, const char *plural, long long n)
{
    const auto &c = catalog();
    if (auto *e = find(singular)) {
        if (c.lang->nplurals <= 1 || !e->plural)
            return e->str;
        return n != 1 ? e->plural : e->str;
    }
    return n != 1 ? plural : singular;
}

std::string format(std::string_view fmt, std::span<const std::string> args, long long n)
{
    std::string out;
    out.reserve(fmt.size() + 16);
    size_t next = 0;
    for (size_t i = 0; i < fmt.size(); ++i) {
        const char ch = fmt[i];
        if (ch == '{' && i + 1 < fmt.size() && fmt[i + 1] == '{') {
            out.push_back('{');
            ++i;
        } else if (ch == '}' && i + 1 < fmt.size() && fmt[i + 1] == '}') {
            out.push_back('}');
            ++i;
        } else if (ch == '{') {
            const size_t close = fmt.find('}', i);
            if (close == std::string_view::npos) {
                out.append(fmt.substr(i));
                break;
            }
            const std::string_view name = fmt.substr(i + 1, close - i - 1);
            if (name.empty()) {
                if (next < args.size())
                    out.append(args[next]);
                ++next;
            } else if (name == "n") {
                out.append(std::to_string(n));
            } else if (std::all_of(name.begin(), name.end(), [](char d) { return d >= '0' && d <= '9'; })) {
                const size_t idx = size_t(std::stoul(std::string(name)));
                if (idx < args.size())
                    out.append(args[idx]);
            } else {
                out.append(fmt.substr(i, close - i + 1)); // not a placeholder: keep it
            }
            i = close;
        } else {
            out.push_back(ch);
        }
    }
    return out;
}

} // namespace nsp
